{"plan_json": "{
  "objectives": [
    {
      "id": 1,
      "objective": "Research ETD signal composition: fraction of BSE-derived signal (direct BSE, SE2, SE3) in SE mode, with literature values from Peters, Reimer, Goldstein, Seiler, Joy",
      "rationale": "Part (1) asks for specific literature measurements of BSE-derived fraction in ETD SE-mode images",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 2,
      "objective": "Research how BSE fraction in ETD changes for light elements (Al, Z=13) and at low beam energy (~5 kV), including SE yield Z-dependence through SE2 term",
      "rationale": "Part (1) specifically asks about light matrix and low kV effects on BSE contribution",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 3,
      "objective": "Research whether ETD SE-mode images show Z-contrast on flat polished multiphase specimens, and comparison with dedicated BSE detector",
      "rationale": "Part (2) asks about atomic number contrast in ETD vs BSE detectors",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 4,
      "objective": "Research other contrast mechanisms: edge/topographic effects, charging of insulating particles, contamination effects in ETD images",
      "rationale": "Part (3) asks about non-Z-contrast mechanisms that make features bright",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 5,
      "objective": "Research whether dedicated BSE detector confirmation establishes higher Z vs topography/charging",
      "rationale": "Part (3) asks how strongly BSE detector confirmation establishes Z-contrast",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 6,
      "objective": "Research backscatter coefficients at 5 kV for Al, Si, Al2O3, SiO2, SiC, C (diamond), Mg2Si, Fe-rich intermetallics, and Fe; compare with 20-30 kV values",
      "rationale": "Part (4) asks for specific BSE coefficients and whether ordering is preserved at low kV",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 7,
      "objective": "Create summary artifacts and submit final answer",
      "rationale": "Need to organize findings into clear artifacts and provide comprehensive cited answer",
      "status": "pending",
      "result": null,
      "evaluation": null
    }
  ]
}"}

